import type { Project } from "@/lib/projects";

type ProjectListProps = {
  projects: readonly Project[];
  headingId?: string;
  compact?: boolean;
};

/** host + path, no protocol — e.g. github.com/dhruv2mars/repo */
function prettyUrl(url: string): string {
  try {
    const u = new URL(url);
    return `${u.host}${u.pathname.replace(/\/$/, "")}`;
  } catch {
    return url;
  }
}

/**
 * Divided CV rows — name → one-line desc → url ↗ → year.
 * Identity from hairlines and ink shifts; no cards, no hover chrome.
 */
export function ProjectList({
  projects,
  headingId,
  compact = false,
}: ProjectListProps) {
  return (
    <ul
      className={compact ? "cv-list mt-5" : "cv-list mt-8"}
      {...(headingId ? { "aria-labelledby": headingId } : {})}
    >
      {projects.map((project) => (
        <li key={project.name}>
          <a
            href={project.url}
            target="_blank"
            rel="noopener noreferrer"
            className="cv-row"
          >
            <span className="flex min-w-0 flex-1 flex-col gap-x-3 gap-y-0.5 sm:flex-row sm:items-baseline">
              <span className="cv-row-name">{project.name}</span>
              <span className="cv-row-desc">{project.description}</span>
            </span>
            <span className="cv-row-meta">
              <span>{prettyUrl(project.url)} ↗</span>
              {project.year !== undefined ? (
                <span>{project.year}</span>
              ) : null}
            </span>
          </a>
        </li>
      ))}
    </ul>
  );
}

"use client";

import { useEffect, useState } from "react";

const formatter = new Intl.DateTimeFormat("en-US", {
  hour: "2-digit",
  minute: "2-digit",
  second: "2-digit",
  hourCycle: "h23",
  timeZoneName: "short",
});

/**
 * Live local clock — quiet "this person is shipping right now" signal.
 * Mount-only render to avoid server/client timezone mismatch.
 */
export function LocalTime() {
  const [label, setLabel] = useState<string | null>(null);

  useEffect(() => {
    const update = () => setLabel(formatter.format(new Date()));
    update();
    const id = window.setInterval(update, 1000);
    return () => window.clearInterval(id);
  }, []);

  return (
    <span className="tabular-nums" aria-label="Local time">
      {label ?? "--:--:--"}
    </span>
  );
}

